"""Instala TODO lo de Simón en un solo paso (sin zip ni tar).
Ejecutar dentro de la carpeta del proyecto (donde esta app.py):
    python instalar_simon.py
Se puede repetir sin problema."""
import base64, zlib, pathlib, subprocess, sys

ARCHIVOS = {
    'static/js/simon.js': "",
    'static/css/simon.css': "",
    'static/img/simon.png': "",
    'static/js/chat.js': "",
    'conocimiento.py': "",
    'aplicar_simon.py': "",
    'aplicar_respuestas.py': "",
}

raiz = pathlib.Path.cwd()
if not (raiz / "app.py").exists() or not (raiz / "templates").is_dir():
    raise SystemExit("Esta no es la carpeta del proyecto (no veo app.py ni templates).\n"
                     "Entra con:  cd %USERPROFILE%\\bienestarbot   y vuelve a ejecutar.")
print("Carpeta del proyecto:", raiz)

for ruta, datos in ARCHIVOS.items():
    destino = raiz / ruta
    destino.parent.mkdir(parents=True, exist_ok=True)
    destino.write_bytes(zlib.decompress(base64.b64decode(datos)))
    print("  escrito:", ruta)

for script in ("aplicar_simon.py", "aplicar_respuestas.py"):
    print("\n>>", script)
    r = subprocess.run([sys.executable, script], cwd=raiz)
    if r.returncode != 0:
        raise SystemExit(f"{script} termino con error. Copia lo que salio arriba y mandamelo.")

def tiene(ruta, texto):
    return texto in (raiz / ruta).read_text(encoding="utf-8", errors="ignore")

print("\n===== VERIFICACION =====")
print("chat.js escribe poco a poco :", "SI" if tiene("static/js/chat.js", "escribirTodos") else "NO")
print("Simon flotante (sin pantalla):", "SI" if tiene("static/js/simon.js", "function visitante") else "NO")
print("chatbot.py explica deportes  :", "SI" if tiene("chatbot.py", "conocimiento") else "NO")
print("base.html carga a Simon      :", "SI" if tiene("templates/base.html", "simon.css") else "NO")
print("\nAhora reinicia el servidor (Ctrl+C y python app.py) y recarga con Ctrl+F5.")
